import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address originalOwner, address newOwner, address other) public {
        vm.assume(originalOwner != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(other != address(0));
        vm.assume(originalOwner != newOwner);
        vm.assume(originalOwner != other);
        vm.assume(newOwner != other);

        // Set up original owner
        vm.prank(originalOwner);
        c.transferOwnership(originalOwner);

        // Original owner transfers to newOwner
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);

        // Now newOwner should be able to call onlyOwner functions.
        // The reference contract allows this; the buggy contract does not because owner is still msg.sender (originalOwner).
        vm.prank(newOwner);
        bool ok = true;
        try c.owned() {} catch { ok = false; }

        assertTrue(ok, "newOwner should pass onlyOwner check after ownership transfer");
    }
}

