pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // 1. Restrict to admissible domain: caller must be the current owner.
        //    The fuzzer picks newOwner; we become the owner before each run.
        //    We cannot use prank before transferOwnership because onlyOwner checks msg.sender == owner.
        //    So we first make ourselves the owner by calling transferOwnership with our own address
        //    while we are already the owner (initial owner is deployer, i.e. this test contract).
        //    Then we prank and call transferOwnership with the fuzzed newOwner.
        //    But we need to ensure the initial deployer is owner. setUp() deploys with this as msg.sender,
        //    so c.owner() == address(this). That is true.

        // 2. Fuzz the newOwner, call transferOwnership as the current owner (us).
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // 3. Assert: after a successful call, owner must be newOwner.
        assertTrue(c.owner() == newOwner);
    }
}

