pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // The constructor of C (default) sets owner to address(0) or whatever the compiler default is.
        // We need an owner that we can prank as. We set it by calling transferOwnership as the deployer
        // using the initial state. The onlyOwner modifier checks msg.sender == owner.
        // In the default contract, owner is address(0) after deployment.
        // We can prank as address(0) to set an owner, then prank as that owner for the fuzz test.
        vm.prank(address(0));
        c.transferOwnership(address(this));
    }

    function testFuzz_property(address newOwner) public {
        // PRECONDITION: The caller must be the current owner.
        // The fuzzer supplies newOwner.
        vm.assume(newOwner != address(0)); // transfer to zero is technically allowed but we keep it simple.

        // State before: owner is address(this) (set in setUp).
        // We prank as the current owner (address(this)).
        vm.prank(address(this));

        // Try the transferOwnership call.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C should succeed (ok == true) for the current owner.
        // The buggy version always reverts, so ok == false.
        assertTrue(ok);
    }
}

