pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // actor and newOwner are fuzzed; the only admissible condition is that actor is the current owner
        vm.assume(actor != address(0));
        // Set the owner to the fuzzed actor
        vm.prank(c.owner());
        c.transferOwnership(actor);
        // Now actor is the owner; attempt transferOwnership to newOwner
        vm.prank(actor);
        try c.transferOwnership(newOwner) returns (address) {
            // transferOwnership does not return a value, so the try/catch just detects success/revert
            // On success, the reference contract updates owner; the buggy contract never reaches here
            assertEq(c.owner(), newOwner);
        } catch {
            // On revert, the reference contract should never revert for the current owner,
            // so this catch block is only reached by the buggy version. We assert that the owner
            // did not change, which is true for the bug, but the reference never takes this path.
            assertTrue(false, "reference should not revert for current owner");
        }
    }
}

