pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // The owner is initially address(0)
    }

    function testFuzz_property(address caller) public {
        // 1. No vm.assume needed – we want to test for every possible caller
        // 2. Set msg.sender to the caller and attempt to call owned()
        vm.prank(caller);
        // If caller is owner, owned() should succeed; if not, it should revert.
        // We check: if caller == owner, then call MUST NOT revert.
        // Since no external adversarial party is needed, no helper contract is required.

        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // 3. General rule: if the caller is the owner, the call must succeed.
        // The reference always satisfies this; the buggy version (require(false)) always reverts,
        // so it will fail when caller == owner.
        if (caller == c.owner()) {
            assertTrue(ok);
        }
    }
}

