pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64 value, address caller) public {
        // 1. keep value strictly positive to force a non-zero callvalue, the adversarial domain
        vm.assume(value > 0);
        // save the initial owner
        address initialOwner = c.owner();
        // 2. drive c through a call to owned with fuzzed value and caller
        vm.deal(caller, value);
        vm.prank(caller);
        (bool success,) = address(c).call{value: value}(abi.encodeWithSignature("owned()"));
        // 3. exactly one assertion: after a non-zero-value call to owned, the owner MUST remain unchanged
        assertTrue(c.owner() == initialOwner);
    }
}

